"""Fingerprint unchanged model bytes and the preparation algorithm; no geometry reduction."""
from pathlib import Path
import hashlib,json
root=Path(__file__).resolve().parents[1]
source=(root/'index.html').read_text()
def digest(value): return hashlib.sha256(value).hexdigest()
# Include the entire preparation/geometry code region, excluding generated files.
algorithm=source[source.index('function deckLoops('):source.index('function updateCabinProjection(')]+source[source.index('async function runGeometryWork('):source.index('const boatBerths=') if 'const boatBerths=' in source else source.index('const boatBerths={},')]
models={'sail':['default-yacht.glb.gz.part-01','default-yacht.glb.gz.part-02'],'luxury':['luxury-yacht.glb.gz.part-01','luxury-yacht.glb.gz.part-02'],'motor':['xo-270-fc.glb']}
assets={};water={}
for kind,paths in models.items():
 hashes=[]
 for path in paths:
  data=(root/path).read_bytes();sha=digest(data);hashes.append(sha)
  assets['./'+path]={'bytes':len(data),'sha256':sha,'cdnPath':'models/'+sha+'/'+path,'githubPath':path}
 revision=digest((digest(algorithm.encode())+''.join(hashes)+kind).encode())
 path='water-data/'+kind+'.'+revision[:20]+'.json.gz'
 water[kind]={'revision':revision,'path':'./'+path}
 file=root/path
 if file.exists():
  data=file.read_bytes();sha=digest(data)
  assets['./'+path]={'bytes':len(data),'sha256':sha,'cdnPath':'water-data/'+sha+'/'+file.name}
manifest={'schema':1,'assets':assets,'water':water}
(root/'asset-manifest.mjs').write_text('// Generated by scripts/build-asset-manifest.py\nexport const ASSET_MANIFEST='+json.dumps(manifest,separators=(',',':'))+';\n')
(root/'water-data'/'revisions.json').write_text(json.dumps(water,indent=2)+'\n')
print('Asset manifest:',len(assets),'files;',sum(x['bytes'] for x in assets.values()),'bytes; water sidecars',sum((root/w['path'][2:]).exists() for w in water.values()),'/3')
# HTML must not pick up a stale imported manifest after a new deployment.
import re
for filename in ('index.html','template.html'):
 page=root/filename;text=page.read_text()
 for module in ('asset-manifest.mjs','asset-loader.mjs'):
  version=digest((root/module).read_bytes())[:16]
  text=re.sub(r"from '\./"+re.escape(module)+r"(?:\?v=[a-f0-9]+)?'", "from './"+module+'?v='+version+"'",text)
 page.write_text(text)
